pub fn activeLeaseModelId(buffer: []u8) ?[]const u8 {
    if (model_source.partObjectModelId()) |model_id| return model_id;
    if (z3d.g_model_session_token == 0) return null;
    return std.fmt.bufPrint(buffer, "session:{d}", .{z3d.g_model_session_token}) catch null;
}

pub const MutationLease = struct { receipt_id: u64, owned: bool };

pub fn acquireMutationLease(label: []const u8) ?z3d.MutationLease {
    // A historical specimen owns the viewport while the resident document is
    // parked. No hidden edit, undo, redo, gizmo, or topology command may obtain
    // mutation admission until that specimen is explicitly released.
    if (!z3d.residentMutationAllowed(.geometry_journal)) return null;
    if (z3d.g_authorized_model_write_receipt != 0) {
        if (!z3d.g_model_write_leases.owns(z3d.g_authorized_model_write_receipt)) return null;
        return .{ .receipt_id = z3d.g_authorized_model_write_receipt, .owned = false };
    }
    // A retained restore/field/gizmo receipt blocks every unrelated journal
    // mutation before the operation can obtain its preimage.
    if (z3d.g_model_write_leases.owner() != null) return null;
    var model_buffer: [64]u8 = undefined;
    const model_id = z3d.activeLeaseModelId(&model_buffer) orelse return null;
    const receipt_id = z3d.g_model_write_leases.acquire(.{
        .actor = "native",
        .operation_id = label,
        .model_id = model_id,
        .session_token = z3d.g_model_session_token,
        .generation = z3d.g_edit_generation,
    }) catch return null;
    return .{ .receipt_id = receipt_id, .owned = true };
}

pub fn releaseMutationLease(receipt_id: u64, owned: bool) void {
    if (!owned or receipt_id == 0) return;
    _ = z3d.g_model_write_leases.release(receipt_id) catch {};
}

pub fn captureJournalSelection() ?z3d.JournalSelection {
    const mode = mesh_edit.mode();
    var result = z3d.JournalSelection{ .mode = mode };
    errdefer result.deinit();
    switch (mode) {
        .none => {},
        .vertex => {
            if (!mesh_edit.ensureTopologyPub()) return null;
            var rows: std.ArrayListUnmanaged(u32) = .empty;
            defer rows.deinit(z3d.jalloc);
            var vertex: u32 = 0;
            while (vertex < mesh_edit.vertCount()) : (vertex += 1) {
                if (mesh_edit.vertSelectedPub(vertex)) rows.append(z3d.jalloc, vertex) catch return null;
            }
            if (rows.items.len > 0) result.vertex_ids = rows.toOwnedSlice(z3d.jalloc) catch return null;
        },
        .edge => {
            if (!mesh_edit.ensureTopologyPub()) return null;
            var rows: std.ArrayListUnmanaged(mesh_edit.Edge) = .empty;
            defer rows.deinit(z3d.jalloc);
            var edge: u32 = 0;
            while (edge < mesh_edit.edgeCount()) : (edge += 1) {
                if (mesh_edit.edgeSelectedPub(edge)) rows.append(z3d.jalloc, mesh_edit.edgeEndpointsPub(edge)) catch return null;
            }
            if (rows.items.len > 0) result.edge_pairs = rows.toOwnedSlice(z3d.jalloc) catch return null;
        },
        .face => {
            const face_count: usize = @intCast(z3d.g_edit_count / 3);
            if (face_count > 0) {
                result.face_mask = z3d.jalloc.alloc(bool, face_count) catch return null;
                for (result.face_mask, 0..) |*selected, face| selected.* = mesh_edit.faceSelectedPub(@intCast(face));
            }
        },
    }
    return result;
}

pub fn restoreJournalSelection(selection: *const z3d.JournalSelection) bool {
    mesh_edit.clearSelection();
    switch (selection.mode) {
        .none => mesh_edit.setMode(.none),
        .vertex => {
            mesh_edit.setMode(.vertex);
            for (selection.vertex_ids, 0..) |vertex, index| {
                if (!mesh_edit.selectVertexByIndex(vertex, index != 0)) return false;
            }
        },
        .edge => {
            mesh_edit.setMode(.edge);
            if (selection.edge_pairs.len > 0 and
                mesh_edit.selectEdgesByEndpointPairsPub(selection.edge_pairs, false) != @as(u32, @intCast(selection.edge_pairs.len)))
            {
                return false;
            }
        },
        .face => {
            mesh_edit.setMode(.face);
            if (selection.face_mask.len > 0) _ = mesh_edit.selectFacesByTriangleMask(selection.face_mask);
        },
    }
    return true;
}

