pub fn meshActionDrain(out: []z3d.MeshActionEvent) usize {
    // Run any armed roll call now — every op's door has long returned. Two-strike
    // protocol: a first faulty pass stays SILENT and re-checks next drain, so a
    // gesture whose bookkeeping settles a beat after its commit never false-alarms;
    // a fault that survives both passes heals/reports, landing in this same drain
    // right behind the op events that caused it.
    if (z3d.g_integrity_pending) {
        const label = z3d.g_integrity_label_buf[0..z3d.g_integrity_label_len];
        if (z3d.meshIntegrityCheck(label, z3d.g_integrity_strikes >= 1)) {
            if (z3d.g_integrity_strikes >= 1) {
                z3d.g_integrity_pending = false;
                z3d.g_integrity_strikes = 0;
            } else z3d.g_integrity_strikes = 1;
        } else {
            z3d.g_integrity_pending = false;
            z3d.g_integrity_strikes = 0;
        }
    }
    const n = @min(out.len, z3d.g_mesh_action_len);
    if (n == 0) return 0;
    @memcpy(out[0..n], z3d.g_mesh_action_events[0..n]);
    const remain = z3d.g_mesh_action_len - n;
    if (remain > 0) std.mem.copyForwards(z3d.MeshActionEvent, z3d.g_mesh_action_events[0..remain], z3d.g_mesh_action_events[n..z3d.g_mesh_action_len]);
    z3d.g_mesh_action_len = remain;
    return n;
}

pub fn journalEntryBytes(e: *const z3d.JournalEntry) usize {
    var n: usize = (e.source_verts.len + e.verts.len) * @sizeOf(f32);
    if (e.groups) |g| n += g.len * @sizeOf(u32);
    if (e.materials) |m| n += m.len * @sizeOf(u32);
    if (e.semantic_regions) |rows| n += rows.len * @sizeOf(u32);
    if (e.semantic_instances) |rows| n += rows.len * @sizeOf(u32);
    if (e.logical_ids) |rows| n += rows.len * @sizeOf(u32);
    if (e.semantic_table_json) |json| n += json.len;
    if (e.part_ranges) |p| n += p.len * @sizeOf(u32);
    if (e.part_object_ids_json) |json| n += json.len;
    if (e.part_object_model_id) |model_id| n += model_id.len;
    if (e.part_object_ids) |rows| {
        n += rows.len * @sizeOf([]u8);
        for (rows) |row| n += row.len;
    }
    if (e.colors) |c| n += c.len;
    n += e.hidden.len * @sizeOf(z3d.JournalHidden);
    for (e.hidden) |h| {
        n += (h.verts.len + h.source_verts.len) * @sizeOf(f32);
        n += h.groups.len * @sizeOf(u32) + h.materials.len * @sizeOf(u32) + h.colors.len;
        n += (h.semantic_regions.len + h.semantic_instances.len) * @sizeOf(u32);
        if (h.logical_ids) |rows| n += rows.len * @sizeOf(u32);
    }
    if (e.atlas) |atlas| n += atlas.rgba.len;
    if (e.paint_state) |paint_state| n += paint_program.journalStateBytes(paint_state);
    if (e.retopo_guide) |guide| {
        n += guide.live_bands.len * @sizeOf(u16);
        n += guide.source_positions.len * @sizeOf(f32);
        n += guide.source_bands.len * @sizeOf(u16);
    }
    if (e.uv_zones) |rows| n += rows.len * @sizeOf(u16);
    if (e.note) |note| n += note.len;
    n += e.selection.vertex_ids.len * @sizeOf(u32);
    n += e.selection.edge_pairs.len * @sizeOf(mesh_edit.Edge);
    n += e.selection.face_mask.len * @sizeOf(bool);
    return n;
}

pub fn journalFreeEntry(e: *z3d.JournalEntry) void {
    z3d.releaseMutationLease(e.mutation_lease_receipt, e.mutation_lease_owned);
    e.mutation_lease_receipt = 0;
    e.mutation_lease_owned = false;
    z3d.jalloc.free(e.source_verts);
    z3d.jalloc.free(e.verts);
    if (e.groups) |g| z3d.jalloc.free(g);
    if (e.materials) |m| z3d.jalloc.free(m);
    if (e.semantic_regions) |rows| z3d.jalloc.free(rows);
    if (e.semantic_instances) |rows| z3d.jalloc.free(rows);
    if (e.logical_ids) |rows| z3d.jalloc.free(rows);
    if (e.semantic_table_json) |json| z3d.jalloc.free(json);
    if (e.part_ranges) |p| z3d.jalloc.free(p);
    if (e.part_object_ids_json) |json| z3d.jalloc.free(json);
    if (e.part_object_model_id) |model_id| z3d.jalloc.free(model_id);
    if (e.part_object_ids) |rows| {
        for (rows) |row| z3d.jalloc.free(row);
        z3d.jalloc.free(rows);
    }
    if (e.colors) |c| z3d.jalloc.free(c);
    for (e.hidden) |h| z3d.freeJournalHidden(h);
    if (e.hidden.len > 0) z3d.jalloc.free(e.hidden);
    if (e.atlas) |atlas| z3d.jalloc.free(atlas.rgba);
    if (e.paint_state) |paint_state| paint_program.journalStateFree(paint_state);
    if (e.retopo_guide) |*guide| guide.deinit(z3d.jalloc);
    if (e.uv_zones) |rows| z3d.jalloc.free(rows);
    if (e.note) |n| z3d.jalloc.free(n);
    e.selection.deinit();
}

pub fn journalFreeStack(stack: *std.ArrayListUnmanaged(z3d.JournalEntry)) void {
    for (stack.items) |*e| z3d.journalFreeEntry(e);
    stack.clearRetainingCapacity();
}

pub fn cloneStringRows(rows: []const []const u8) ![][]u8 {
    const cloned = try z3d.jalloc.alloc([]u8, rows.len);
    var initialized: usize = 0;
    errdefer {
        for (cloned[0..initialized]) |row| z3d.jalloc.free(row);
        z3d.jalloc.free(cloned);
    }
    for (rows, 0..) |row, index| {
        cloned[index] = try z3d.jalloc.dupe(u8, row);
        initialized += 1;
    }
    return cloned;
}

pub fn journalSnapshotCurrentInner(label: []const u8, new_document_action: bool) ?z3d.JournalEntry {
    const mutation_lease = z3d.acquireMutationLease(label) orelse return null;
    var release_lease = true;
    defer if (release_lease) z3d.releaseMutationLease(mutation_lease.receipt_id, mutation_lease.owned);
    // Reserve the eventual undo slot before any caller is allowed to mutate.
    // Commit then cannot lose its preimage to an allocation failure.
    z3d.g_journal_undo.ensureUnusedCapacity(z3d.jalloc, 1) catch return null;
    const verts = z3d.g_edit_verts orelse return null;
    // g_edit_count == 0 is a valid EMPTY snapshot (req_2806): stepping the journal
    // away from an emptied model must be able to record "it was empty" for redo.
    const need = @as(usize, z3d.g_edit_count) * 8;
    if (verts.len < need) return null;
    const source_rows = if (model_source.verts()) |rows|
        if (model_source.count() == z3d.g_edit_count and rows.len >= need) rows[0..need] else verts[0..need]
    else
        verts[0..need];
    const source_verts = z3d.jalloc.dupe(f32, source_rows) catch return null;
    const v = z3d.jalloc.dupe(f32, verts[0..need]) catch {
        z3d.jalloc.free(source_verts);
        return null;
    };
    var entry = z3d.JournalEntry{
        .generation = z3d.g_edit_generation,
        .source_verts = source_verts,
        .verts = v,
        .count = z3d.g_edit_count,
        .groups = null,
        .materials = null,
        .semantic_regions = null,
        .semantic_instances = null,
        .logical_ids = null,
        .logical_vertex_count = model_source.logicalVertexCount(),
        .semantic_table_json = null,
        .part_ranges = null,
        .part_object_ids_json = null,
        .part_object_model_id = null,
        .part_object_ids = null,
        .colors = null,
        .hidden = &.{},
        .atlas = null,
        .paint_state = null,
        .retopo_guide = null,
        .uv_zones = null,
        .paint_layout_stale = z3d.g_paint_layout_stale,
        .paint_layout_revision = model_paint.layoutRevision(),
        .note = null,
        .selection = .{},
        .label = label,
        .action_id = 0,
        .action_kind = null,
        .mutation_lease_receipt = mutation_lease.receipt_id,
        .mutation_lease_owned = mutation_lease.owned,
    };
    const restore_domain = mesh_journal_log.restoreDomainForLabel(label);
    if (restore_domain == .atlas or restore_domain == .paint) {
        const atlas = model_paint.atlas() orelse {
            z3d.journalFreeEntry(&entry);
            return null;
        };
        if (atlas.rgba.len > z3d.JOURNAL_ATLAS_BYTE_CAP) {
            z3d.journalFreeEntry(&entry);
            return null;
        }
        const rgba = z3d.jalloc.dupe(u8, atlas.rgba) catch {
            z3d.journalFreeEntry(&entry);
            return null;
        };
        entry.atlas = .{ .rgba = rgba, .w = atlas.w, .h = atlas.h };
    }
    if (restore_domain == .uv or restore_domain == .atlas or restore_domain == .paint) {
        entry.paint_state = (if (new_document_action)
            paint_program.journalStateCaptureForNewAction()
        else
            paint_program.journalStateCapture()) orelse {
            z3d.journalFreeEntry(&entry);
            return null;
        };
    }
    if (model_source.faceGroups() != null) {
        entry.groups = z3d.captureFaceGroups() orelse {
            z3d.journalFreeEntry(&entry);
            release_lease = false;
            return null;
        };
    }
    if (model_source.faceMaterials()) |rows| entry.materials = z3d.jalloc.dupe(u32, rows) catch {
        z3d.journalFreeEntry(&entry);
        release_lease = false;
        return null;
    };
    if (model_source.faceSemanticRegions()) |rows| entry.semantic_regions = z3d.jalloc.dupe(u32, rows) catch {
        z3d.journalFreeEntry(&entry);
        release_lease = false;
        return null;
    };
    if (model_source.faceSemanticInstances()) |rows| entry.semantic_instances = z3d.jalloc.dupe(u32, rows) catch {
        z3d.journalFreeEntry(&entry);
        release_lease = false;
        return null;
    };
    if (model_source.renderCornerLogicalIds()) |rows| {
        if (rows.len != z3d.g_edit_count) {
            z3d.journalFreeEntry(&entry);
            return null;
        }
        entry.logical_ids = z3d.jalloc.dupe(u32, rows) catch {
            z3d.journalFreeEntry(&entry);
            return null;
        };
    }
    if (model_source.semanticTableJson()) |json| entry.semantic_table_json = z3d.jalloc.dupe(u8, json) catch {
        z3d.journalFreeEntry(&entry);
        release_lease = false;
        return null;
    };
    if (model_source.partRanges()) |pr| entry.part_ranges = z3d.jalloc.dupe(u32, pr) catch {
        z3d.journalFreeEntry(&entry);
        release_lease = false;
        return null;
    };
    const object_ids_json = model_source.partObjectIdsJson();
    const object_model_id = model_source.partObjectModelId();
    if ((object_ids_json == null) != (object_model_id == null)) {
        z3d.journalFreeEntry(&entry);
        release_lease = false;
        return null;
    }
    if (object_ids_json) |json| {
        entry.part_object_ids_json = z3d.jalloc.dupe(u8, json) catch {
            z3d.journalFreeEntry(&entry);
            release_lease = false;
            return null;
        };
        entry.part_object_model_id = z3d.jalloc.dupe(u8, object_model_id.?) catch {
            z3d.journalFreeEntry(&entry);
            release_lease = false;
            return null;
        };
        var parsed_ids = std.json.parseFromSlice([]const []const u8, z3d.jalloc, json, .{}) catch {
            z3d.journalFreeEntry(&entry);
            release_lease = false;
            return null;
        };
        defer parsed_ids.deinit();
        entry.part_object_ids = z3d.cloneStringRows(parsed_ids.value) catch {
            z3d.journalFreeEntry(&entry);
            release_lease = false;
            return null;
        };
    }
    if (z3d.meshRetopoGuideSnapshot()) |guide| {
        entry.retopo_guide = z3d.cloneRetopoGuide(guide) orelse {
            z3d.journalFreeEntry(&entry);
            return null;
        };
    }
    if (z3d.g_uv_zone) |rows| entry.uv_zones = z3d.jalloc.dupe(u16, rows) catch {
        z3d.journalFreeEntry(&entry);
        return null;
    };
    entry.colors = z3d.collectCurrentFaceColors() orelse {
        z3d.journalFreeEntry(&entry);
        release_lease = false;
        return null;
    };
    if (z3d.g_hidden_groups.items.len > 0) {
        var hs: std.ArrayListUnmanaged(z3d.JournalHidden) = .empty;
        defer {
            for (hs.items) |hidden| z3d.freeJournalHidden(hidden);
            hs.deinit(z3d.jalloc);
        }
        for (z3d.g_hidden_groups.items) |h| {
            entry.logical_vertex_count = @max(entry.logical_vertex_count, h.logical_vertex_count);
            const clone = z3d.cloneJournalHidden(h) catch {
                z3d.journalFreeEntry(&entry);
                return null;
            };
            hs.append(z3d.jalloc, clone) catch {
                z3d.freeJournalHidden(clone);
                z3d.journalFreeEntry(&entry);
                return null;
            };
        }
        entry.hidden = hs.toOwnedSlice(z3d.jalloc) catch {
            z3d.journalFreeEntry(&entry);
            return null;
        };
    }
    if (z3d.g_journal_note) |n| entry.note = z3d.jalloc.dupe(u8, n) catch {
        z3d.journalFreeEntry(&entry);
        release_lease = false;
        return null;
    };
    entry.selection = z3d.captureJournalSelection() orelse {
        z3d.journalFreeEntry(&entry);
        release_lease = false;
        return null;
    };
    release_lease = false;
    return entry;
}

pub fn journalSnapshotCurrent(label: []const u8) ?z3d.JournalEntry {
    return z3d.journalSnapshotCurrentInner(label, false);
}

pub fn journalSnapshotForNewAction(label: []const u8) ?z3d.JournalEntry {
    return z3d.journalSnapshotCurrentInner(label, true);
}

pub fn armIntegrityRollCall(label: []const u8) void {
    const n = @min(label.len, z3d.g_integrity_label_buf.len);
    @memcpy(z3d.g_integrity_label_buf[0..n], label[0..n]);
    z3d.g_integrity_label_len = n;
    z3d.g_integrity_pending = true;
    z3d.g_integrity_strikes = 0; // a fresh op restarts the two-strike audit
}

/// A face's three corner positions as exact bit patterns, rotated so the
/// lexicographically-smallest corner leads WITHOUT changing winding — so
/// (a,b,c) and (b,c,a) canonicalize identically but a reversed twin does not.
/// Null for wire/degenerate faces (any two corners exactly coincident): those
/// are deliberate (Pen Edges) and never audited.
pub fn canonicalFaceBits(verts: []const f32, face: u32) ?[9]u32 {
    var corners: [3][3]u32 = undefined;
    for (0..3) |corner| {
        const base = (@as(usize, face) * 3 + corner) * 8;
        corners[corner] = .{
            @bitCast(verts[base]),
            @bitCast(verts[base + 1]),
            @bitCast(verts[base + 2]),
        };
    }
    if (std.mem.eql(u32, &corners[0], &corners[1]) or
        std.mem.eql(u32, &corners[1], &corners[2]) or
        std.mem.eql(u32, &corners[0], &corners[2])) return null;
    var lead: usize = 0;
    for (1..3) |corner| {
        if (std.mem.order(u32, &corners[corner], &corners[lead]) == .lt) lead = corner;
    }
    var out: [9]u32 = undefined;
    for (0..3) |slot| {
        const corner = corners[(lead + slot) % 3];
        @memcpy(out[slot * 3 .. slot * 3 + 3], &corner);
    }
    return out;
}

/// One audit pass over the document. Detect-only mode (act=false) heals and
/// reports NOTHING — the two-strike drain protocol gives a gesture's own
/// bookkeeping one drain cycle (~250ms) to finish: loop cut renormalizes its
/// ranges after journalCommit inside the same door, but a single-part doc can
/// skip that leg and settle through later machinery, and the drain timer can
/// land inside that window (observed headlessly: transient unowned=8/16 on a
/// healthy chain). A fault that survives TWO consecutive drains is real:
/// then heal what is provable and go loud. Returns whether a fault was seen.
pub fn meshIntegrityCheck(context: []const u8, act: bool) bool {
    const displayed_faces: usize = @intCast(z3d.g_edit_count / 3);
    var total_faces: usize = displayed_faces;
    for (z3d.g_hidden_groups.items) |hidden| total_faces += hidden.groups.len;
    const declared_before = z3d.currentPartCount();
    if (total_faces == 0 and declared_before == 0) return false;
    const alloc = std.heap.c_allocator;
    const groups = alloc.alloc(u32, total_faces) catch return false;
    defer alloc.free(groups);
    var face: u32 = 0;
    while (face < displayed_faces) : (face += 1) groups[face] = model_source.faceGroupOf(face);
    var write: usize = displayed_faces;
    for (z3d.g_hidden_groups.items) |hidden| {
        @memcpy(groups[write .. write + hidden.groups.len], hidden.groups);
        write += hidden.groups.len;
    }
    const check = struct {
        pub fn run(a: std.mem.Allocator, rows: []const u32) ?mesh_journal_log.StateSummary {
            return mesh_journal_log.analyze(a, .{
                .vertex_count = @intCast(rows.len * 3),
                .groups = rows,
                .part_ranges = model_source.partRanges(),
            }) catch null;
        }
    };
    var summary = check.run(alloc, groups) orelse return false;
    var faulted = false;
    var healed = false;
    if (!summary.ranges_valid) {
        faulted = true;
        if (act) {
            healed = z3d.ensureDisjointPartRanges(context);
            summary.deinit(alloc);
            summary = check.run(alloc, groups) orelse return true;
        }
    }
    defer summary.deinit(alloc);
    if (summary.ranges_valid and summary.unowned_faces == 0 and summary.multiply_owned_faces == 0) {
        var empty_declarations: usize = 0;
        for (summary.parts) |part| {
            if (part.faces == 0) empty_declarations += 1;
        }
        if (empty_declarations > 0) {
            faulted = true;
            if (act) {
                if (model_source.partRanges()) |ranges| {
                    if (mesh_journal_log.compactOccupiedPartRanges(alloc, groups, ranges)) |compacted| {
                        model_source.setPartRanges(compacted);
                        alloc.free(compacted);
                        healed = true;
                    } else |_| {}
                }
            }
        }
    } else faulted = true;
    // Geometric tripwire (req_3486): an exact same-winding duplicate face is
    // ALWAYS a fault — fromSoup collapses them at the import boundary, so any
    // live one was minted by the op that just committed. Reversed twins
    // (extrude's interior walls) are legal internal structure, and wire faces
    // ((a,b,b) deliberate degenerates) are excluded by the coincident-corner
    // skip. Report-only: the next indexed lowering collapses them anyway; the
    // value here is naming the guilty op instead of shredding N cuts later.
    var duplicate_faces: u32 = 0;
    if (z3d.g_edit_verts) |verts| {
        var seen = std.AutoHashMapUnmanaged(u64, u32).empty;
        defer seen.deinit(alloc);
        var probe: u32 = 0;
        while (probe < displayed_faces) : (probe += 1) {
            const canon = z3d.canonicalFaceBits(verts, probe) orelse continue;
            const key = std.hash.Wyhash.hash(0, std.mem.asBytes(&canon));
            const gop = seen.getOrPut(alloc, key) catch break;
            if (gop.found_existing) {
                const other = z3d.canonicalFaceBits(verts, gop.value_ptr.*) orelse continue;
                if (std.mem.eql(u32, &canon, &other)) {
                    duplicate_faces += 1;
                    faulted = true;
                }
            } else gop.value_ptr.* = probe;
        }
    }
    if (!faulted or !act) return faulted;
    const declared_after = z3d.currentPartCount();
    std.log.err(
        "[mesh-integrity] roll call after '{s}': ranges_valid={} unowned={d} multiply_owned={d} duplicate_faces={d} declared {d}->{d} healed={} (req_3484)",
        .{ context, summary.ranges_valid, summary.unowned_faces, summary.multiply_owned_faces, duplicate_faces, declared_before, declared_after, healed },
    );
    z3d.g_mesh_action_seq +%= 1;
    if (z3d.g_mesh_action_seq == 0) z3d.g_mesh_action_seq = 1;
    z3d.enqueueMeshAction(z3d.g_mesh_action_seq, .integrity_alert, .applied, z3d.g_edit_count, z3d.g_edit_count, declared_before, declared_after);
    return true;
}

/// Adopt a pre-op snapshot as an undo step (the op SUCCEEDED). Clears redo and
/// bounds the stack. Sets *snap to null so the op's discard defer no-ops.
pub fn journalCommit(snap: *?z3d.JournalEntry) void {
    z3d.g_last_committed_action_id = 0;
    var e = snap.* orelse return;
    snap.* = null;
    const admitted = e.mutation_lease_receipt != 0 and
        z3d.g_model_write_leases.owns(e.mutation_lease_receipt) and
        (e.mutation_lease_owned or z3d.g_authorized_model_write_receipt == e.mutation_lease_receipt);
    if (!admitted) {
        // The mutation lost admission after its preimage was captured.  Restore
        // that exact preimage before returning; a stale/competing operation may
        // never become an unjournalled resident edit.
        if (!z3d.journalInstall(&e) or !z3d.journalResidentDurableMatches(&e)) {
            std.log.err("[mesh-journal] lost-admission rollback could not verify exact preimage", .{});
        }
        z3d.journalFreeEntry(&e);
        return;
    }
    var follow_kind: u8 = 255; // unmapped journal labels still belong in the firehose
    z3d.g_mesh_action_seq +%= 1;
    if (z3d.g_mesh_action_seq == 0) z3d.g_mesh_action_seq = 1;
    e.action_id = z3d.g_mesh_action_seq;
    z3d.g_last_committed_action_id = e.action_id;
    if (mesh_journal_log.actionKindForLabel(e.label)) |kind| {
        follow_kind = @intFromEnum(kind);
        if (mesh_journal_log.actionInvalidatesPaintLayout(kind)) z3d.g_paint_layout_stale = true;
        e.action_kind = kind;
        z3d.enqueueMeshAction(
            e.action_id,
            kind,
            .applied,
            e.count,
            z3d.g_edit_count,
            z3d.partCountFromRanges(e.part_ranges),
            z3d.currentPartCount(),
        );
    }
    if (mesh_journal_log.faceAnalysisGenerationNeedsAdvance(
        e.action_kind,
        e.generation,
        z3d.g_edit_generation,
    )) z3d.bumpEditRevision();
    z3d.enqueueFollowJournalAction(
        e.action_id,
        follow_kind,
        .applied,
        e.label,
        e.count,
        z3d.g_edit_count,
        z3d.partCountFromRanges(e.part_ranges),
        z3d.currentPartCount(),
    );
    z3d.armIntegrityRollCall(e.label);
    z3d.journalFreeStack(&z3d.g_journal_redo);
    z3d.releaseMutationLease(e.mutation_lease_receipt, e.mutation_lease_owned);
    e.mutation_lease_receipt = 0;
    e.mutation_lease_owned = false;
    z3d.g_journal_undo.appendAssumeCapacity(e);
    var total: usize = 0;
    for (z3d.g_journal_undo.items) |*it| total += z3d.journalEntryBytes(it);
    while (total > z3d.JOURNAL_BYTE_BUDGET and z3d.g_journal_undo.items.len > 1) {
        var old = z3d.g_journal_undo.orderedRemove(0);
        total -= z3d.journalEntryBytes(&old);
        z3d.journalFreeEntry(&old);
    }
}

/// Free an untaken snapshot (the op failed or changed nothing).
pub fn journalDiscard(snap: *?z3d.JournalEntry) void {
    if (snap.*) |e| {
        var x = e;
        z3d.journalFreeEntry(&x);
    }
    snap.* = null;
}

/// Drop the newest undo entry — used when a guard REVERT returns the mesh to the
/// exact state the entry snapshots (undoing to it would be a visible no-op).
pub fn journalDropLast() void {
    if (z3d.g_journal_undo.items.len == 0) return;
    var e = z3d.g_journal_undo.items[z3d.g_journal_undo.items.len - 1];
    z3d.g_journal_undo.items.len -= 1;
    if (e.action_kind) |kind| {
        z3d.enqueueMeshAction(
            e.action_id,
            kind,
            .undone,
            z3d.g_edit_count,
            e.count,
            z3d.currentPartCount(),
            z3d.partCountFromRanges(e.part_ranges),
        );
    }
    z3d.enqueueFollowJournalAction(
        e.action_id,
        if (e.action_kind) |kind| @intFromEnum(kind) else 255,
        .undone,
        e.label,
        z3d.g_edit_count,
        e.count,
        z3d.currentPartCount(),
        z3d.partCountFromRanges(e.part_ranges),
    );
    z3d.journalFreeEntry(&e);
}

/// Forget all history — a fresh model load is a new document.
pub fn meshJournalClear() void {
    z3d.semanticMintIntentClear();
    mesh_edit.curvePullEnd();
    z3d.curvePullAdaptiveReset();
    z3d.g_curve_pull_preserve_gizmo_guard = false;
    z3d.g_integrity_pending = false; // an armed check must not audit the NEXT document
    z3d.g_integrity_strikes = 0;
    z3d.journalFreeStack(&z3d.g_journal_undo);
    z3d.journalFreeStack(&z3d.g_journal_redo);
    z3d.journalDiscard(&z3d.g_gizmo_snap);
    z3d.lcFree(); // a live loop-cut popup can't outlive the mesh it captured
    z3d.bevelFree(); // nor can a live bevel preview / captured base
    z3d.quadifyDrop(); // nor can a dry-run topology plan outlive its document
    if (z3d.g_journal_note) |n| z3d.jalloc.free(n);
    z3d.g_journal_note = null;
    z3d.g_mesh_action_source = .native;
    z3d.g_follow_action_queue.clear(z3d.jalloc);
    z3d.g_authorized_model_write_receipt = 0;
    z3d.g_model_write_leases.reset();
    z3d.g_model_adoption_receipts.reset();
    z3d.g_last_committed_action_id = 0;
}

pub fn meshJournalNoteSet(note: []const u8) bool {
    if (!z3d.residentMutationAllowed(.metadata_journal)) return false;
    const next = z3d.jalloc.dupe(u8, note) catch return false;
    if (z3d.g_journal_note) |n| z3d.jalloc.free(n);
    z3d.g_journal_note = next;
    return true;
}

pub fn meshJournalNoteGet() ?[]const u8 {
    return z3d.g_journal_note;
}

pub fn meshJournalCounts() [2]u32 {
    return .{ @intCast(z3d.g_journal_undo.items.len), @intCast(z3d.g_journal_redo.items.len) };
}

/// Append one metadata-only edit to the SAME journal as geometry. The explicit
/// before note makes rapid React commands deterministic even when the effect
/// that normally mirrors g_journal_note has not run between clicks.
pub fn meshJournalMetadataCheckpoint(label: []const u8, before_note: []const u8, after_note: []const u8) bool {
    if (!z3d.residentMutationAllowed(.metadata_journal)) return false;
    if (!mesh_journal_log.metadataCheckpointValid(before_note, after_note)) return false;
    if (!z3d.meshJournalNoteSet(before_note)) return false;
    var snap = z3d.journalSnapshotCurrent(label);
    if (snap == null) return false;
    if (snap.?.note == null) {
        z3d.journalDiscard(&snap);
        return false;
    }
    if (!z3d.meshJournalNoteSet(after_note)) {
        z3d.journalDiscard(&snap);
        return false;
    }
    z3d.journalCommit(&snap);
    return true;
}

pub fn meshJournalMetadataCheckpointLabel(kind: []const u8) ?[]const u8 {
    return mesh_journal_log.metadataCheckpointLabel(kind);
}

pub fn journalLogEntryView(entry: *const z3d.JournalEntry) mesh_journal_log.EntryView {
    return .{
        .label = entry.label,
        .state = .{
            .vertex_count = entry.count,
            .groups = entry.groups,
            .part_ranges = entry.part_ranges,
            .hidden_parts = entry.hidden.len,
            .bytes = z3d.journalEntryBytes(entry),
            .note = entry.note,
        },
    };
}

pub fn journalCurrentStateBytes(groups: ?[]const u32) usize {
    var bytes = @as(usize, z3d.g_edit_count) * 8 * @sizeOf(f32);
    if (groups) |rows| bytes += rows.len * @sizeOf(u32);
    if (model_source.faceMaterials()) |rows| bytes += rows.len * @sizeOf(u32);
    if (model_source.faceSemanticRegions()) |rows| bytes += rows.len * @sizeOf(u32);
    if (model_source.faceSemanticInstances()) |rows| bytes += rows.len * @sizeOf(u32);
    if (model_source.renderCornerLogicalIds()) |rows| bytes += rows.len * @sizeOf(u32);
    if (model_source.semanticTableJson()) |json| bytes += json.len;
    if (model_source.partRanges()) |ranges| bytes += ranges.len * @sizeOf(u32);
    if (model_source.colors()) |colors| bytes += colors.len;
    bytes += z3d.g_hidden_groups.items.len * @sizeOf(z3d.HiddenGroup);
    for (z3d.g_hidden_groups.items) |hidden| {
        bytes += (hidden.verts.len + hidden.source_verts.len) * @sizeOf(f32);
        bytes += hidden.groups.len * @sizeOf(u32) + hidden.materials.len * @sizeOf(u32) + hidden.colors.len;
        bytes += (hidden.semantic_regions.len + hidden.semantic_instances.len) * @sizeOf(u32);
        if (hidden.logical_ids) |rows| bytes += rows.len * @sizeOf(u32);
    }
    if (z3d.g_journal_note) |note| bytes += note.len;
    if (z3d.meshRetopoGuideSnapshot()) |guide| {
        bytes += guide.live_bands.len * @sizeOf(u16);
        bytes += guide.source_positions.len * @sizeOf(f32);
        bytes += guide.source_bands.len * @sizeOf(u16);
    }
    return bytes;
}

/// Full, bounded in-memory edit history for the model surface's right-click
/// diagnostics. Every snapshot includes topology counts and exact outliner
/// group-range ownership; redo is emitted in the order it will be replayed.
pub fn meshJournalLogJson(allocator: std.mem.Allocator) ?[]u8 {
    const undo = allocator.alloc(mesh_journal_log.EntryView, z3d.g_journal_undo.items.len) catch return null;
    defer allocator.free(undo);
    for (z3d.g_journal_undo.items, 0..) |*entry, index| undo[index] = z3d.journalLogEntryView(entry);

    const redo = allocator.alloc(mesh_journal_log.EntryView, z3d.g_journal_redo.items.len) catch return null;
    defer allocator.free(redo);
    for (0..z3d.g_journal_redo.items.len) |index| {
        const source_index = z3d.g_journal_redo.items.len - 1 - index;
        redo[index] = z3d.journalLogEntryView(&z3d.g_journal_redo.items[source_index]);
    }

    const current_groups: ?[]u32 = if (model_source.faceGroups() != null) z3d.captureFaceGroups() else null;
    defer if (current_groups) |groups| z3d.jalloc.free(groups);

    var journal_bytes: usize = 0;
    for (z3d.g_journal_undo.items) |*entry| journal_bytes += z3d.journalEntryBytes(entry);
    for (z3d.g_journal_redo.items) |*entry| journal_bytes += z3d.journalEntryBytes(entry);
    if (z3d.g_gizmo_snap) |*entry| journal_bytes += z3d.journalEntryBytes(entry);

    // The journal's ownership table can be perfectly healthy while a stale live edit
    // scope hides most of the part (req_2953). Include both the scope and the two edge
    // vocabularies so the copied log distinguishes render triangulation from authored
    // topology without relying on a screenshot.
    var scope_storage: [mesh_edit.max_scope_ranges * 2]u32 = undefined;
    const scope_len = mesh_edit.scopeRangesPub(scope_storage[0..]);
    const topology: ?mesh_journal_log.TopologyView = if (mesh_edit.ensureTopologyPub()) .{
        .welded_vertices = mesh_edit.vertCount(),
        .triangle_edges = mesh_edit.edgeCount(),
        .editable_edges = mesh_edit.boundaryEdgeCount(),
    } else null;

    return mesh_journal_log.encode(allocator, .{
        .capacity = 0, // 0 = no entry-count cap; byte_budget is the wall (req_4700)
        .byte_budget = z3d.JOURNAL_BYTE_BUDGET,
        .journal_bytes = journal_bytes,
        .pending_gizmo = z3d.g_gizmo_snap != null,
        .pending_loop_cut = z3d.g_lc != null,
        .scope_ranges = scope_storage[0..scope_len],
        .topology = topology,
        .undo = undo,
        .current = .{
            .vertex_count = z3d.g_edit_count,
            .groups = current_groups,
            .part_ranges = model_source.partRanges(),
            .hidden_parts = z3d.g_hidden_groups.items.len,
            .bytes = z3d.journalCurrentStateBytes(current_groups),
            .note = z3d.g_journal_note,
        },
        .redo = redo,
    }) catch null;
}

/// The resident mesh-editor SESSION (req_2898 hot-reload resume). A dev hot reload
/// tears down the JS world but this process — the live edit mesh, its journal, the
/// authored paint atlas, and the orbit pose — all survive. This readback gives the
/// remounted viewer everything it needs to decide "the host still holds my live document":
/// adopt it instead of re-loading the stale seed (which would wipe the edits).
/// Null when no edit mesh is resident (cold boot / viewer never loaded).
pub fn modelSessionJson(alloc: std.mem.Allocator) ?[]u8 {
    const key = z3d.g_edit_key orelse return null;
    const j = z3d.meshJournalCounts();
    var out: std.ArrayList(u8) = .empty;
    errdefer out.deinit(alloc);
    out.appendSlice(alloc, "{\"key\":\"") catch return null;
    for (key) |ch| switch (ch) {
        '"' => out.appendSlice(alloc, "\\\"") catch return null,
        '\\' => out.appendSlice(alloc, "\\\\") catch return null,
        0...31 => {
            var print_buf: [8]u8 = undefined;
            const rendered = std.fmt.bufPrint(&print_buf, "\\u{x:0>4}", .{ch}) catch return null;
            out.appendSlice(alloc, rendered) catch return null;
        },
        else => out.append(alloc, ch) catch return null,
    };
    var print_buf: [192]u8 = undefined;
    const rendered = std.fmt.bufPrint(&print_buf, "\",\"count\":{d},\"generation\":{d},\"radius\":{d:.6},\"undo\":{d},\"redo\":{d},\"atlas\":{},\"paintStale\":{}}}", .{
        z3d.g_edit_count, z3d.g_edit_generation, z3d.g_orbit.radius, j[0], j[1], model_paint.hasAuthoredAtlas(), z3d.g_paint_layout_stale,
    }) catch return null;
    out.appendSlice(alloc, rendered) catch return null;
    return out.toOwnedSlice(alloc) catch null;
}

pub fn meshUndoLabel() []const u8 {
    if (z3d.g_journal_undo.items.len == 0) return "";
    return z3d.g_journal_undo.items[z3d.g_journal_undo.items.len - 1].label;
}
pub fn meshRedoLabel() []const u8 {
    if (z3d.g_journal_redo.items.len == 0) return "";
    return z3d.g_journal_redo.items[z3d.g_journal_redo.items.len - 1].label;
}

pub fn journalInstallUv(e: *const z3d.JournalEntry) bool {
    if (e.count != z3d.g_edit_count) return false;
    const retained_state = e.paint_state orelse return false;
    const atlas = model_paint.atlas() orelse return false;
    const corners = z3d.jalloc.alloc(f32, @as(usize, e.count) * 2) catch return false;
    defer z3d.jalloc.free(corners);
    if (!mesh_journal_log.writeAtlasCornersFromInterleavedUv(e.verts, e.count, atlas.w, atlas.h, corners)) return false;
    const paint_state = paint_program.journalStateClone(retained_state) orelse return false;
    if (!z3d.applyUvCornerGeometry(corners)) {
        paint_program.journalStateFree(paint_state);
        return false;
    }
    paint_program.journalStateAdopt(paint_state);
    z3d.g_paint_layout_stale = e.paint_layout_stale;
    return true;
}

pub fn journalInstallAtlas(e: *const z3d.JournalEntry) bool {
    const atlas = e.atlas orelse return false;
    if (e.count != z3d.g_edit_count) return false;
    const retained_state = e.paint_state orelse return false;
    const paint_state = paint_program.journalStateClone(retained_state) orelse return false;
    const installed = if (std.mem.eql(u8, e.label, mesh_journal_log.UV_ATLAS_RESIZE_LABEL))
        z3d.resizePaintAtlas(atlas.rgba, atlas.w, atlas.h)
    else
        z3d.importPaintAtlas(atlas.rgba, atlas.w, atlas.h);
    if (!installed) {
        paint_program.journalStateFree(paint_state);
        return false;
    }
    paint_program.journalStateAdopt(paint_state);
    z3d.g_paint_layout_stale = e.paint_layout_stale;
    return true;
}

/// Selection paint owns three synchronized truths: the exact raster, the
/// replayable paint program, and source-face RGB used by later quality changes.
/// Texture import restores only the first two; this domain restores all three.
pub fn journalInstallPaint(e: *const z3d.JournalEntry) bool {
    const atlas = e.atlas orelse return false;
    if (e.count != z3d.g_edit_count) return false;
    const retained_state = e.paint_state orelse return false;
    const paint_state = paint_program.journalStateClone(retained_state) orelse return false;
    if (!z3d.resizePaintAtlas(atlas.rgba, atlas.w, atlas.h)) {
        paint_program.journalStateFree(paint_state);
        return false;
    }
    paint_program.journalStateAdopt(paint_state);
    if (e.colors) |colors| z3d.restoreFaceColorMetadata(colors);
    z3d.g_paint_layout_stale = e.paint_layout_stale;
    return true;
}

pub fn journalInstallRetopoGuide(e: *const z3d.JournalEntry) bool {
    if (e.retopo_guide) |*guide| return z3d.meshRetopoGuideRestore(guide.view());
    _ = z3d.clearRetopoBandPreview();
    return true;
}

pub fn journalInstallUvZones(e: *const z3d.JournalEntry) bool {
    const replacement: ?[]u16 = if (e.uv_zones) |rows| z3d.jalloc.dupe(u16, rows) catch return false else null;
    if (z3d.g_uv_zone) |rows| z3d.jalloc.free(rows);
    z3d.g_uv_zone = replacement;
    z3d.publishUvZoneMask();
    return true;
}

/// Prove every channel that can be checked without touching resident state.
/// Install is intentionally allocation-light after this boundary; any remaining
/// late allocation refusal is handled by the caller's exact preimage rollback.
pub fn journalMeshPreflight(e: *const z3d.JournalEntry) bool {
    if (e.count % 3 != 0) return false;
    const vertex_rows = @as(usize, e.count) * 8;
    const face_count = @as(usize, e.count / 3);
    if (e.verts.len != vertex_rows or e.source_verts.len != vertex_rows) return false;
    if (e.groups) |rows| if (rows.len != face_count) return false;
    if (e.materials) |rows| if (rows.len != face_count) return false;
    if ((e.semantic_regions == null) != (e.semantic_instances == null)) return false;
    if (e.semantic_regions) |rows| {
        if (rows.len != face_count or e.semantic_instances.?.len != face_count) return false;
        for (rows, e.semantic_instances.?) |region, instance| {
            if (region == model_source.NO_SEMANTIC_ID and instance != model_source.NO_SEMANTIC_ID) return false;
        }
    }
    if (e.colors == null or e.colors.?.len != face_count * 4) return false;
    if (e.uv_zones) |rows| if (rows.len != face_count) return false;
    if (e.logical_ids) |rows| {
        if (rows.len != e.count or e.logical_vertex_count == 0 or
            !meshdoc_format.logicalRowsValid(z3d.jalloc, e.source_verts, rows, e.logical_vertex_count, false)) return false;
    } else if (e.logical_vertex_count != 0) return false;

    const range_count: u32 = if (e.part_ranges) |rows| @intCast(rows.len / 2) else 0;
    if (!meshdoc_format.rangesValid(e.part_ranges, range_count)) return false;
    if ((e.part_object_ids_json == null) != (e.part_object_model_id == null) or
        (e.part_object_ids_json == null) != (e.part_object_ids == null)) return false;
    if (e.part_object_ids_json) |json| {
        _ = json;
        if (e.part_object_model_id.?.len == 0 or range_count == 0) return false;
        const object_ids = e.part_object_ids.?;
        if (object_ids.len != range_count) return false;
        for (object_ids, 0..) |object_id, index| {
            if (object_id.len == 0 or std.mem.indexOfScalar(u8, object_id, 0) != null) return false;
            for (object_ids[0..index]) |prior| if (std.mem.eql(u8, prior, object_id)) return false;
        }
    }

    switch (e.selection.mode) {
        .none => if (e.selection.vertex_ids.len != 0 or e.selection.edge_pairs.len != 0 or e.selection.face_mask.len != 0) return false,
        .vertex => {
            if (e.selection.edge_pairs.len != 0 or e.selection.face_mask.len != 0) return false;
            for (e.selection.vertex_ids, 0..) |vertex, index| {
                for (e.selection.vertex_ids[0..index]) |prior| if (prior == vertex) return false;
            }
        },
        .edge => {
            if (e.selection.vertex_ids.len != 0 or e.selection.face_mask.len != 0) return false;
            for (e.selection.edge_pairs, 0..) |edge, index| {
                if (edge[0] == edge[1]) return false;
                for (e.selection.edge_pairs[0..index]) |prior| {
                    const same = (prior[0] == edge[0] and prior[1] == edge[1]) or
                        (prior[0] == edge[1] and prior[1] == edge[0]);
                    if (same) return false;
                }
            }
        },
        .face => if (e.selection.vertex_ids.len != 0 or e.selection.edge_pairs.len != 0 or e.selection.face_mask.len != face_count) return false,
    }
    return true;
}

pub fn optionalU32RowsEqual(a: ?[]const u32, b: ?[]const u32) bool {
    if ((a == null) != (b == null)) return false;
    return a == null or std.mem.eql(u32, a.?, b.?);
}

pub fn optionalBytesEqual(a: ?[]const u8, b: ?[]const u8) bool {
    if ((a == null) != (b == null)) return false;
    return a == null or std.mem.eql(u8, a.?, b.?);
}

pub fn journalSelectionMatches(selection: *const z3d.JournalSelection) bool {
    if (mesh_edit.mode() != selection.mode) return false;
    switch (selection.mode) {
        .none => return true,
        .vertex => {
            if (!mesh_edit.ensureTopologyPub()) return false;
            var selected_count: usize = 0;
            var vertex: u32 = 0;
            while (vertex < mesh_edit.vertCount()) : (vertex += 1) {
                if (!mesh_edit.vertSelectedPub(vertex)) continue;
                selected_count += 1;
                if (std.mem.indexOfScalar(u32, selection.vertex_ids, vertex) == null) return false;
            }
            return selected_count == selection.vertex_ids.len;
        },
        .edge => {
            if (!mesh_edit.ensureTopologyPub()) return false;
            var selected_count: usize = 0;
            var edge_index: u32 = 0;
            while (edge_index < mesh_edit.edgeCount()) : (edge_index += 1) {
                if (!mesh_edit.edgeSelectedPub(edge_index)) continue;
                selected_count += 1;
                const edge = mesh_edit.edgeEndpointsPub(edge_index);
                var found = false;
                for (selection.edge_pairs) |prior| {
                    if ((prior[0] == edge[0] and prior[1] == edge[1]) or
                        (prior[0] == edge[1] and prior[1] == edge[0]))
                    {
                        found = true;
                        break;
                    }
                }
                if (!found) return false;
            }
            return selected_count == selection.edge_pairs.len;
        },
        .face => {
            if (selection.face_mask.len != z3d.g_edit_count / 3) return false;
            for (selection.face_mask, 0..) |selected, face| {
                if (mesh_edit.faceSelectedPub(@intCast(face)) != selected) return false;
            }
            return true;
        },
    }
}

/// Verification for the exact resident channels represented by the journal.
/// Working paint UVs may be rebuilt, so durable source rows are the geometry
/// authority for this comparison.
pub fn journalResidentDurableMatches(e: *const z3d.JournalEntry) bool {
    if (z3d.g_edit_count != e.count or model_source.count() != e.count) return false;
    const source = model_source.verts() orelse return e.source_verts.len == 0;
    if (!std.mem.eql(u8, std.mem.sliceAsBytes(source), std.mem.sliceAsBytes(e.source_verts))) return false;
    if (!z3d.optionalU32RowsEqual(model_source.faceGroups(), e.groups)) return false;
    if (!z3d.optionalU32RowsEqual(model_source.faceMaterials(), e.materials)) return false;
    if (!z3d.optionalU32RowsEqual(model_source.faceSemanticRegions(), e.semantic_regions)) return false;
    if (!z3d.optionalU32RowsEqual(model_source.faceSemanticInstances(), e.semantic_instances)) return false;
    if (!z3d.optionalU32RowsEqual(model_source.renderCornerLogicalIds(), e.logical_ids)) return false;
    if (model_source.logicalVertexCount() != e.logical_vertex_count) return false;
    if (!z3d.optionalBytesEqual(model_source.semanticTableJson(), e.semantic_table_json)) return false;
    if (!z3d.optionalU32RowsEqual(model_source.partRanges(), e.part_ranges)) return false;
    if (!z3d.optionalBytesEqual(model_source.partObjectIdsJson(), e.part_object_ids_json)) return false;
    if (!z3d.optionalBytesEqual(model_source.partObjectModelId(), e.part_object_model_id)) return false;
    if (!z3d.optionalBytesEqual(model_source.colors(), e.colors)) return false;
    if (!z3d.optionalBytesEqual(z3d.g_journal_note, e.note)) return false;
    if ((z3d.g_uv_zone == null) != (e.uv_zones == null)) return false;
    if (z3d.g_uv_zone) |rows| if (!std.mem.eql(u16, rows, e.uv_zones.?)) return false;
    if (z3d.g_hidden_groups.items.len != e.hidden.len) return false;
    for (z3d.g_hidden_groups.items, e.hidden) |live, saved| {
        if (live.lo != saved.lo or live.hi != saved.hi or
            live.logical_vertex_count != saved.logical_vertex_count or
            !std.mem.eql(u8, std.mem.sliceAsBytes(live.verts), std.mem.sliceAsBytes(saved.verts)) or
            !std.mem.eql(u8, std.mem.sliceAsBytes(live.source_verts), std.mem.sliceAsBytes(saved.source_verts)) or
            !std.mem.eql(u32, live.groups, saved.groups) or
            !std.mem.eql(u32, live.materials, saved.materials) or
            !std.mem.eql(u32, live.semantic_regions, saved.semantic_regions) or
            !std.mem.eql(u32, live.semantic_instances, saved.semantic_instances) or
            !z3d.optionalU32RowsEqual(live.logical_ids, saved.logical_ids) or
            !std.mem.eql(u8, live.colors, saved.colors)) return false;
    }
    return z3d.journalSelectionMatches(&e.selection);
}

pub fn cloneOptionalU32Rows(rows: ?[]const u32) !?[]u32 {
    return if (rows) |values| try z3d.jalloc.dupe(u32, values) else null;
}

/// Convert one already-validated current RJMD document into the exact state the
/// resident journal installs. No field is inferred from the current resident.
pub fn journalEntryFromDocument(
    document: *const meshdoc_format.Document,
    model_id: []const u8,
    label: []const u8,
) !z3d.JournalEntry {
    if (document.version != meshdoc_format.VERSION_LOGICAL_TOPOLOGY or
        document.verts.len == 0 or document.verts.len % 24 != 0 or
        document.range_object_ids == null or document.range_object_ids.?.len == 0 or
        document.ranges.len != document.range_object_ids.?.len * 2)
    {
        return error.InvalidDocument;
    }
    const vertex_count: u32 = @intCast(document.verts.len / 8);
    const face_count: usize = @intCast(vertex_count / 3);
    const source_verts = try z3d.jalloc.dupe(f32, document.verts);
    errdefer z3d.jalloc.free(source_verts);
    const displayed_verts = try z3d.jalloc.dupe(f32, document.verts);
    errdefer z3d.jalloc.free(displayed_verts);
    var entry = z3d.JournalEntry{
        .generation = z3d.g_edit_generation,
        .source_verts = source_verts,
        .verts = displayed_verts,
        .count = vertex_count,
        .groups = null,
        .materials = null,
        .semantic_regions = null,
        .semantic_instances = null,
        .logical_ids = null,
        .logical_vertex_count = document.logical_vertex_count,
        .semantic_table_json = null,
        .part_ranges = null,
        .part_object_ids_json = null,
        .part_object_model_id = null,
        .part_object_ids = null,
        .colors = null,
        .hidden = &.{},
        .atlas = null,
        .paint_state = null,
        .retopo_guide = null,
        .uv_zones = null,
        .paint_layout_stale = true,
        // Lore carries RJMD geometry, not the current paint atlas/program. Force
        // the restore down the stale-layout rebuild path even when counts happen
        // to match; arbitrary historical topology never inherits atlas validity.
        .paint_layout_revision = model_paint.layoutRevision() +% 1,
        .note = null,
        .selection = .{ .mode = .none },
        .label = label,
        .action_id = 0,
        .action_kind = null,
        .mutation_lease_receipt = 0,
        .mutation_lease_owned = false,
    };
    errdefer z3d.journalFreeEntry(&entry);
    entry.groups = try z3d.cloneOptionalU32Rows(document.groups);
    entry.materials = try z3d.cloneOptionalU32Rows(document.materials);
    entry.semantic_regions = try z3d.cloneOptionalU32Rows(document.semantic_regions);
    entry.semantic_instances = try z3d.cloneOptionalU32Rows(document.semantic_instances);
    entry.logical_ids = try z3d.cloneOptionalU32Rows(document.render_corner_logical_ids);
    if (document.semantic_table_json) |json| entry.semantic_table_json = try z3d.jalloc.dupe(u8, json);
    entry.part_ranges = try z3d.jalloc.dupe(u32, document.ranges);
    entry.part_object_ids_json = try std.json.Stringify.valueAlloc(z3d.jalloc, document.range_object_ids.?, .{});
    entry.part_object_model_id = try z3d.jalloc.dupe(u8, model_id);
    entry.part_object_ids = try z3d.cloneStringRows(document.range_object_ids.?);
    const colors = try z3d.jalloc.alloc(u8, face_count * 4);
    entry.colors = colors;
    for (0..face_count) |face| {
        const base = face * 4;
        colors[base + 0] = model_paint.DEFAULT_FACE[0];
        colors[base + 1] = model_paint.DEFAULT_FACE[1];
        colors[base + 2] = model_paint.DEFAULT_FACE[2];
        colors[base + 3] = model_paint.DEFAULT_FACE[3];
    }
    if (document.glass_first_vertex) |first_vertex| {
        if (first_vertex > vertex_count or first_vertex % 3 != 0) return error.InvalidDocument;
        var face: usize = first_vertex / 3;
        while (face < face_count) : (face += 1) colors[face * 4 + 3] = model_paint.GLASS_ALPHA;
    }
    if (z3d.g_journal_note) |note| entry.note = try z3d.jalloc.dupe(u8, note);
    if (!z3d.journalMeshPreflight(&entry)) return error.InvalidDocument;
    return entry;
}

/// Install a snapshot as the live mesh (the undo/redo restore path). The entry's
/// buffers stay owned by the caller — every adopt below copies.
pub fn journalInstall(e: *const z3d.JournalEntry) bool {
    switch (mesh_journal_log.restoreDomainForLabel(e.label)) {
        .uv => return z3d.journalInstallUv(e),
        .atlas => return z3d.journalInstallAtlas(e),
        .paint => return z3d.journalInstallPaint(e),
        .retopo_guide => return z3d.journalInstallRetopoGuide(e),
        .mesh => {},
    }
    if (!z3d.journalMeshPreflight(e)) return false;
    const vcopy = z3d.jalloc.dupe(f32, e.verts) catch return false;
    defer z3d.jalloc.free(vcopy);
    const action_kind = e.action_kind orelse mesh_journal_log.actionKindForLabel(e.label);
    const invalidates_layout = if (action_kind) |kind| mesh_journal_log.actionInvalidatesPaintLayout(kind) else false;
    // Indexed structural installs keep the atlas raster alive and journal snapshots
    // retain their exact interleaved UVs. Reuse that raster only while it is still the
    // SAME coordinate space the snapshot recorded. Hide/show performs a group-keyed
    // repack; installing older UVs over that later raster makes opaque faces sample
    // transparent shelf padding (req_3364).
    const same_atlas_coordinates = e.paint_layout_revision == model_paint.layoutRevision();
    const exact_face_reorder = if (action_kind) |kind| kind == .glass_faces else false;
    const preserve_indexed_atlas = (invalidates_layout or exact_face_reorder) and
        same_atlas_coordinates and
        e.count >= 3 and
        model_paint.atlas() != null and
        e.colors != null;
    // Part-only journals add/remove whole stable groups; survivor paint identity is
    // unchanged, so undo/redo preserves exact pixels AND the durable program. Other
    // topology journals may rewrite program identity, but when their old coordinate
    // space is gone they still need a group-keyed raster carry through the rebuild;
    // snapshot colours seed any restored-only face.
    const paint_stable = !preserve_indexed_atlas and z3d.paintStableJournalLabel(e.label);
    const carry_repacked_atlas = !preserve_indexed_atlas and invalidates_layout;
    if (paint_stable)
        z3d.beginPaintStableReplace()
    else if (carry_repacked_atlas)
        z3d.beginPaintRasterCarry();
    const journal_logical = z3d.logicalReplacementForJournalRestore(
        e.logical_ids,
        e.count,
        e.logical_vertex_count,
    );
    const installed = if (preserve_indexed_atlas)
        z3d.replaceActiveEditMeshPreservingAtlas(vcopy, e.count, e.groups, e.colors.?, journal_logical)
    else
        z3d.replaceActiveEditMesh(vcopy, e.count, journal_logical);
    if (!installed) {
        if (paint_stable)
            z3d.cancelPaintStableReplace()
        else if (carry_repacked_atlas)
            z3d.cancelPaintRasterCarry();
        return false;
    }
    // The displayed edit rows may carry paint-atlas UVs. Journal entries also
    // retain the exact durable RJMD source rows; put those back before logical
    // topology validation so Ctrl-Z/Ctrl-Y is byte-faithful, not merely visual.
    if (e.source_verts.len != @as(usize, e.count) * 8 or
        !model_source.replaceGeometrySameTriangleCount(e.source_verts, e.count))
    {
        return false;
    }
    // Hidden-part stash: restore AFTER the install succeeded (independent of the mesh).
    z3d.clearHiddenGroups();
    for (e.hidden) |h| {
        const clone = z3d.cloneHiddenGroup(h) catch continue;
        z3d.g_hidden_groups.append(std.heap.c_allocator, clone) catch z3d.freeHiddenGroup(clone);
    }
    if (e.groups) |g|
        model_source.setFaceGroups(g)
    else
        model_source.clearFaceGroups();
    if (e.materials) |materials|
        model_source.setFaceMaterials(materials)
    else
        model_source.clearFaceMaterials();
    if (e.semantic_regions) |regions| {
        const instances = e.semantic_instances orelse return false;
        if (e.semantic_table_json) |json| {
            if (!model_source.setSemanticState(regions, instances, json)) return false;
        } else if (!model_source.setFaceSemantics(regions, instances)) return false;
    } else model_source.clearFaceSemantics();
    // Logical rows were installed atomically with the geometry replacement above.
    // Tripwire (req_3049): restoring a snapshot that carries NO ranges over a mesh
    // that has them silently un-parts the model — the save then persists a doc that
    // reopens merged. Name it when it happens.
    if (e.part_ranges == null and model_source.partRanges() != null) {
        log.print("[mesh] undo/redo restored a snapshot WITHOUT part ranges over a mesh that had {d} parts — ranges cleared (req_3049)\n", .{model_source.partRanges().?.len / 2});
    }
    model_source.setPartRanges(e.part_ranges orelse &.{});
    if ((e.part_object_ids_json == null) != (e.part_object_model_id == null) or
        (e.part_object_ids_json == null) != (e.part_object_ids == null)) return false;
    if (e.part_object_ids != null) {
        const object_ids: []const []const u8 = e.part_object_ids.?;
        if (!model_source.setPartObjectIds(e.part_object_model_id.?, object_ids)) return false;
    } else model_source.clearPartObjectIds();
    if (e.colors) |c| {
        if (!preserve_indexed_atlas) model_paint.applyColors(c);
        if (model_source.colors()) |src| {
            const n = @min(src.len, c.len);
            if (n > 0) @memcpy(src[0..n], c[0..n]);
        }
        if (preserve_indexed_atlas and exact_face_reorder) {
            var face: u32 = 0;
            while (face < e.count / 3) : (face += 1) {
                model_paint.paintFaceAlpha(face, c[@as(usize, face) * 4 + 3]);
            }
            paint_program.invalidateFaceKeys();
        }
    }
    if (z3d.g_journal_note) |n| z3d.jalloc.free(n);
    z3d.g_journal_note = if (e.note) |n| (z3d.jalloc.dupe(u8, n) catch null) else null;
    // Snapshots taken while the minting bug was live carry overlapped spans (req_3029)
    // — undoing into one must heal it, not resurrect the corruption.
    _ = z3d.ensureDisjointPartRanges("undo/redo restore");
    if (e.count > 0 and !preserve_indexed_atlas) _ = z3d.refreshPaintLayout(); // an EMPTY snapshot has no islands to lay out
    z3d.g_paint_layout_stale = e.paint_layout_stale;
    if (!z3d.journalInstallRetopoGuide(e)) return false;
    if (!z3d.journalInstallUvZones(e)) return false;
    return z3d.restoreJournalSelection(&e.selection);
}

pub fn journalStep(from_undo: bool) bool {
    const src = if (from_undo) &z3d.g_journal_undo else &z3d.g_journal_redo;
    const dst = if (from_undo) &z3d.g_journal_redo else &z3d.g_journal_undo;
    if (src.items.len == 0) return false;
    const top = src.items[src.items.len - 1];
    const top_label = top.label;
    const cur = z3d.journalSnapshotCurrent(top_label) orelse return false;
    var current = cur;
    dst.ensureUnusedCapacity(z3d.jalloc, 1) catch {
        z3d.journalFreeEntry(&current);
        return false;
    };
    current.action_id = top.action_id;
    current.action_kind = top.action_kind;
    var entry = src.items[src.items.len - 1];
    src.items.len -= 1;
    if (!z3d.journalInstall(&entry) or !z3d.journalResidentDurableMatches(&entry)) {
        const rolled_back = z3d.journalInstall(&current) and z3d.journalResidentDurableMatches(&current);
        if (!rolled_back) {
            std.log.err("[mesh-journal] undo/redo target failed and exact resident rollback could not be verified", .{});
        }
        src.append(z3d.jalloc, entry) catch z3d.journalFreeEntry(&entry);
        var c = current;
        z3d.journalFreeEntry(&c);
        return false;
    }
    const phase: mesh_journal_log.ActionPhase = if (from_undo) .undone else .redone;
    if (entry.action_kind) |kind| {
        z3d.enqueueMeshAction(
            entry.action_id,
            kind,
            phase,
            current.count,
            entry.count,
            z3d.partCountFromRanges(current.part_ranges),
            z3d.partCountFromRanges(entry.part_ranges),
        );
    }
    z3d.enqueueFollowJournalAction(
        entry.action_id,
        if (entry.action_kind) |kind| @intFromEnum(kind) else 255,
        phase,
        entry.label,
        current.count,
        entry.count,
        z3d.partCountFromRanges(current.part_ranges),
        z3d.partCountFromRanges(entry.part_ranges),
    );
    z3d.journalFreeEntry(&entry);
    z3d.releaseMutationLease(current.mutation_lease_receipt, current.mutation_lease_owned);
    current.mutation_lease_receipt = 0;
    current.mutation_lease_owned = false;
    dst.appendAssumeCapacity(current);
    z3d.armIntegrityRollCall(if (from_undo) "undo" else "redo");
    return true;
}

pub fn meshUndo() bool {
    if (!z3d.residentMutationAllowed(.geometry_journal)) return false;
    return z3d.journalStep(true);
}
pub fn meshRedo() bool {
    if (!z3d.residentMutationAllowed(.geometry_journal)) return false;
    return z3d.journalStep(false);
}
